export const POPUP_CSS = '\n.dialog-title{flex:1;display:flex;flex-direction:column;gap:2px;padding-top:2px;min-width:0}\n.dialog-title h3{padding-top:0}\n.std-masthead{display:flex;justify-content:center}\n.std-masthead img{max-width:100%;max-height:var(--kit-masthead-h,120px);width:auto;height:auto;display:block}\n.std-issue{margin:0;text-align:center;font:600 13px/1.4 var(--mp-font-ui);color:var(--mp-text-3)}\n.std-footnote{margin:8px 0 0;text-align:center;font-size:12px;line-height:1.4;color:var(--mp-text-3)}\n.std-list>li[data-icon]{list-style:none;display:flex;align-items:center;gap:8px;margin-left:-20px}\n.std-list-icon{flex:none;width:24px;height:24px;object-fit:contain}\n';
export const POPUP_LANDSCAPE_CSS = '\n.std-art:has(>.kit-party){flex-direction:column;gap:12px;flex-shrink:0}\n@media(orientation:landscape) and (max-height:520px){\n .dialog:has(>.std-art+.std-content[data-layout=landscape]){width:min(760px,100%);display:grid;\n  grid-template-columns:minmax(0,5fr) minmax(0,7fr);grid-template-rows:auto auto auto;align-content:start;\n  grid-template-areas:"head head" "art content" "art actions";column-gap:24px}\n .dialog:has(>.std-content[data-layout=landscape])>.dialog-head{grid-area:head}\n .dialog:has(>.std-content[data-layout=landscape])>.std-art{grid-area:art;align-self:start;margin:0;min-height:0}\n .dialog:has(>.std-content[data-layout=landscape])>.std-art>img{max-height:min(220px,50dvh);width:auto}\n .dialog:has(>.std-content[data-layout=landscape])>.std-art:has(>.kit-party)>img{max-height:min(100px,25dvh)}\n .dialog:has(>.std-content[data-layout=landscape])>.std-content{grid-area:content;align-self:center}\n .dialog:has(>.std-content[data-layout=landscape])>.std-actions{grid-area:actions;position:static}\n}';
export const CONFIRM_CSS = '\n.dialog:has(>.cf-item){width:min(358px,100%)}\n.cf-item{display:flex;align-items:center;gap:16px;padding:16px;box-sizing:border-box;\n border-radius:var(--mp-r-m,12px);background:var(--mp-surface);border:1px solid var(--mp-line);text-align:left}\n.cf-tile{flex:0 0 auto;width:56px;height:56px;border-radius:var(--mp-r-m,12px);background:var(--mp-raised);\n display:flex;align-items:center;justify-content:center}\n.cf-tile img,.cf-tile svg{width:40px;height:40px;display:block}\n\n.cf-tile img,.cf-tile [data-part=icon]{width:40px;height:40px;display:block}\n.cf-copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}\n.cf-name{font-weight:700;font-size:17px;line-height:1.3;color:var(--mp-text);overflow-wrap:anywhere}\n.cf-details{color:var(--mp-text-3);font-weight:600;font-size:13px;line-height:1.4}\n.cf-free{align-self:flex-start;height:24px;padding:0 10px;border-radius:var(--mp-r-s,8px);display:flex;\n align-items:center;background:var(--mp-success-soft);color:var(--mp-mint);font-weight:700;font-size:13px}\n.cf-price{flex:0 0 auto;font-weight:700;font-size:17px;color:var(--mp-text)}\n.dialog:has(>.cf-item) .std-actions{margin-top:0}\n.dialog:has(>.cf-item) .std-actions .std-action{min-height:var(--mp-button-h,48px)}\n@media(max-height:480px){.dialog:has(>.cf-item){width:min(384px,100%)}\n .dialog:has(>.cf-item) .std-actions .std-action{flex:1 1 0}}\n';
